export class ApiError extends Error {
  constructor(message, status = 0) { super(message); this.status = status; }
}

export async function requestJson(url, options = {}, timeoutMs = 15000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, { credentials: "same-origin", cache: "no-store", ...options, signal: controller.signal });
    let data;
    try { data = await response.json(); } catch { throw new ApiError("Сервис обработки недоступен.", response.status); }
    if (!response.ok) throw new ApiError(data.detail || "Не удалось выполнить запрос.", response.status);
    return data;
  } catch (error) {
    if (error instanceof ApiError) throw error;
    throw new ApiError("Нет связи с сервером. Проверьте подключение и повторите попытку.");
  } finally { clearTimeout(timer); }
}

// Shared public-report presentation and navigation. No activity data in URLs.
import { formatDuration } from "./run-summary.mjs";

const number = new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 2 });
const percent = value => Number.isFinite(value) ? `${number.format(value)}%` : "—";
export const coverageReasons = {
  invalid_record_timestamps: "Временные метки записи не позволяют выполнить расчёт.",
  unresolved_timer_state: "Не удалось однозначно определить паузы записи.",
  no_active_time: "В записи не найдено активного времени.",
};

export function coverageRefused(report) {
  return report.mode === "fit_only" && ["below_threshold", "unavailable"].includes(report.observed_gps_coverage?.status);
}

export function coverageMessage(coverage) {
  if (coverage?.status === "below_threshold") {
    return `Для восстановления без GPX недостаточно сохранившихся GPS-данных: ${percent(coverage.observed_gps_coverage_percent)} активного времени при минимуме ${percent(coverage.minimum_observed_gps_coverage_percent)}. Выбери FIT повторно и добавь GPX маршрута.`;
  }
  if (coverage?.status === "unavailable") {
    return `Не удалось определить покрытие GPS по времени записи. ${coverageReasons[coverage.reason] || ""} Восстановление без GPX не запущено. Выбери FIT повторно и добавь GPX маршрута.`.replace(/ +/g, " ");
  }
  return "";
}

export function coverageDetails(coverage) {
  if (!coverage) return "Для этого отчёта сведения о GPS-покрытии недоступны.";
  if (coverage.status === "not_applicable") return "С GPX порог GPS-покрытия не применяется.";
  return `Исходное GPS-покрытие: ${percent(coverage.observed_gps_coverage_percent)}. Минимум: ${percent(coverage.minimum_observed_gps_coverage_percent)}. Активное время: ${formatDuration(coverage.active_duration_seconds)}. С GPS: ${formatDuration(coverage.observed_gps_duration_seconds)}.`;
}

export function openSubmittedResult(uid, browser = window) {
  if (!/^[A-Za-z0-9_-]{43}$/.test(uid)) throw new Error("Сервер вернул некорректный результат.");
  // The marker belongs to this navigation entry, not to every visit by the owner.
  browser.history.pushState({ warpbusterUpload: uid }, "", `/res/${uid}`);
  browser.location.reload();
}

export function returnToUpload(report, uid, browser = window) {
  if (!coverageRefused(report) || browser.history.state?.warpbusterUpload !== uid) return false;
  const gate = report.observed_gps_coverage;
  browser.history.replaceState({ warpbusterCoverageRefusal: {
    status: gate.status, reason: gate.reason,
    observed_gps_coverage_percent: gate.observed_gps_coverage_percent,
    minimum_observed_gps_coverage_percent: gate.minimum_observed_gps_coverage_percent,
  } }, "", "/fix");
  browser.location.reload();
  return true;
}

export function finishResultNavigation(uid, browser = window) {
  if (browser.history.state?.warpbusterUpload === uid) browser.history.replaceState(null, "");
}

export function endpointMessage(report) {
  if (report.mode !== "fit_only") return "";
  const kinds = new Set((report.gaps || []).filter(gap => gap.action !== "applied").map(gap => gap.kind));
  const prefix = kinds.has("prefix"), suffix = kinds.has("suffix");
  if (prefix && suffix) return "Начало и конец записи остались без координат: для их восстановления не хватает данных.";
  if (prefix) return "Начало записи осталось без координат: для его восстановления не хватает данных.";
  if (suffix) return "Конец записи остался без координат: для его восстановления не хватает данных.";
  return "";
}

export function coordinateFreeMessage(report) {
  const reconstruction = report.coordinate_free_reconstruction;
  if (report.mode !== "fit_with_course" || report.outcome !== "repaired" || reconstruction?.status !== "applied") return "";
  const distances = [reconstruction.recorded_distance_m, reconstruction.course_distance_m, reconstruction.distance_ratio_error].every(Number.isFinite)
    ? ` Дистанция FIT: ${number.format(reconstruction.recorded_distance_m / 1000)} км; GPX: ${number.format(reconstruction.course_distance_m / 1000)} км; расхождение: ${percent(reconstruction.distance_ratio_error * 100)}.`
    : "";
  return "В исходном FIT не было координат. Координаты всей записи восстановлены по GPX от первой до последней точки в порядке их записи. Положение в каждый момент рассчитано по накопленной дистанции FIT."
    + distances + " Временные метки, записанные дистанция и скорость, высота и показания датчиков сохранены. Это предполагаемый маршрут: фактический путь и направление прохождения не подтверждены.";
}

export function resultMessage(report) {
  if (coverageRefused(report)) return ["Восстановление без GPX не запущено.", "Недостаточно пригодных исходных GPS-данных. Исходный FIT не изменён, исправленный файл не создавался."];
  if (report.outcome === "repaired") return [
    report.partial ? "Трек восстановлен частично." : "Трек обработан.",
    coordinateFreeMessage(report) || (report.partial
      ? "Проверенные изменения сохранены в исправленном FIT. Остальные участки остались невосстановленными. Исходный файл не изменён."
      : "Повреждённые участки восстановлены по доступным GPX и OSM данным. Временные метки и показания датчиков сохранены."),
  ];
  if (report.outcome === "unchanged") return ["Без изменений.", "Ядро не выбрало изменений для записи. Исправленный FIT не создавался."];
  if (report.osm?.status === "unavailable") return ["Восстановление не выполнено: ошибка OSM.", osmFailureMessage(report) + " Исправленный FIT не создавался."];
  return ["Нужно больше уверенности.", "Безопасного варианта исправления не найдено. Исходный FIT не изменён, исправленный файл не создавался. На карте показан исходный трек."];
}

export function osmFailureMessage(report) {
  if (report.osm?.status !== "unavailable") return "";
  const stages = {
    setup: "Не удалось запустить обработку OSM.",
    coverage: "Не удалось подготовить область OSM для восстановления.",
    acquisition: "Не удалось получить данные OSM для восстановления.",
    prepare: "Не удалось подготовить карту OSM для поиска маршрута.",
    routing: "Не удалось выполнить поиск маршрута по OSM.",
  };
  return (stages[report.osm.stage] || "При обработке OSM произошёл технический сбой.") + (report.outcome === "repaired"
    ? " Проверенные изменения сохранены в исправленном FIT. Остальные участки не восстановлены."
    : " Изменения не записаны. На карте показан исходный трек.");
}

export function altitudeMessage(report) {
  const altitude = report.altitude_completion;
  if (!altitude || ["disabled", "not_needed"].includes(altitude.status)) return "";
  return altitude.status === "applied"
    ? `Из DEM заполнена только отсутствующая высота: ${altitude.completed_records} записей. Существующая высота FIT сохранена.`
    : "Отсутствующая высота не дополнена. Имеющиеся значения высоты FIT сохранены.";
}

const gapKinds = { internal: "Внутренний участок", prefix: "Начало записи", suffix: "Конец записи", whole_activity: "Вся запись" };
const gapReasons = {
  no_course: "Нет подходящего пути для восстановления",
  insufficient_observed_gps_coverage: "Недостаточно исходных GPS-данных",
  observed_gps_coverage_unavailable: "Покрытие GPS не определено",
  missing_start_hint: "Недостаточно данных для начала записи",
  missing_finish_hint: "Недостаточно данных для конца записи",
};
export function gapCells(gap) {
  const applied = gap.action === "applied";
  const provider = { gpx: "GPX", osm: "OSM" }[gap.provider];
  const reasons = [...new Set((gap.reasons || []).map(reason => gapReasons[reason]).filter(Boolean))];
  return [String(gap.number), gapKinds[gap.kind] || "Участок", applied ? `Восстановлен${provider ? ` по ${provider}` : ""}` : "Не восстановлен",
    String(applied ? gap.filled_points ?? "—" : gap.unresolved_points ?? "—"),
    applied ? (gap.kind === "whole_activity" && gap.provider === "gpx" ? "Полное восстановление по GPX; фактический путь не подтверждён" : gap.estimated ? "Распределение по времени" : "Вариант прошёл проверки") : reasons.join(". ") || "Недостаточно данных или уверенности"];
}

import { requestJson } from "./api.mjs";
import { coverageMessage, openSubmittedResult } from "./fit-only.mjs?v=023b";

export function validateSelection(files, extension, maxBytes = Infinity) {
  if (files.length !== 1 || !files[0]) return "Добавь один файл в это поле.";
  const file = files[0];
  if (!file.name.toLowerCase().endsWith(`.${extension}`)) {
    return `Здесь нужен файл .${extension.toUpperCase()}. Проверь формат экспорта.`;
  }
  if (file.size === 0) return "Файл пустой. Экспортируй его ещё раз.";
  if (file.size > maxBytes) return `Файл слишком большой. Максимум — ${formatFileSize(maxBytes)}.`;
  return "";
}

export function formatFileSize(bytes) {
  const megabyte = 1024 * 1024;
  const number = new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 1 });
  return bytes >= megabyte
    ? `${number.format(bytes / megabyte)} МБ`
    : `${number.format(Math.max(1, Math.ceil(bytes / 1024)))} КБ`;
}

export function initUploadPage(root, { request = requestJson, browser = window } = {}) {
  const selected = new Map();
  const invalid = new Set();
  const count = root.getElementById("ready-count");
  const button = root.getElementById("analyze-button");
  const note = root.getElementById("analysis-note");
  const submitError = root.getElementById("submit-error");
  const retry = root.getElementById("service-retry");
  let available = false;
  let submitting = false;
  let maxBytes = Infinity;
  let submissionKey = null;
  const refusal = root.getElementById("coverage-refusal");
  refusal.textContent = coverageMessage(browser.history.state?.warpbusterCoverageRefusal);
  refusal.hidden = !refusal.textContent;
  const updateCount = () => {
    count.textContent = invalid.size ? "Проверь выбранные файлы" : selected.has("fit")
      ? (selected.has("gpx") ? "FIT и GPX выбраны" : "FIT выбран — можно начинать") : "Выбери FIT-запись";
    button.disabled = submitting || !available || !selected.has("fit") || invalid.size > 0;
  };

  for (const extension of ["fit", "gpx"]) {
    const input = root.getElementById(`${extension}-file`);
    const card = root.querySelector(`[data-file-card="${extension}"]`);
    const zone = card.querySelector(".drop-zone");
    const row = card.querySelector(".selection-row");
    const name = root.getElementById(`${extension}-selected`);
    const error = root.getElementById(`${extension}-error`);
    const action = root.getElementById(`${extension}-action`);

    const clear = () => {
      submissionKey = null;
      selected.delete(extension);
      invalid.delete(extension);
      input.value = "";
      input.removeAttribute("aria-invalid");
      row.hidden = true;
      name.textContent = "";
      error.hidden = true;
      error.textContent = "";
      card.dataset.selected = "false";
      action.textContent = `Выбрать ${extension.toUpperCase()}-файл`;
      updateCount();
    };

    const choose = (files) => {
      if (submitting) return;
      const message = validateSelection(files, extension, maxBytes);
      clear();
      if (message) {
        invalid.add(extension);
        row.hidden = false;
        name.textContent = "Файл не выбран";
        error.textContent = message;
        error.hidden = false;
        input.setAttribute("aria-invalid", "true");
        updateCount();
        return;
      }
      const file = files[0];
      selected.set(extension, file);
      name.textContent = `${file.name} · ${formatFileSize(file.size)}`;
      row.hidden = false;
      card.dataset.selected = "true";
      action.textContent = `Заменить ${extension.toUpperCase()}-файл`;
      updateCount();
    };

    input.addEventListener("change", () => {
      // Cancelling the picker keeps the previous selection.
      if (input.files.length) choose(Array.from(input.files));
    });
    card.querySelector("[data-remove]").addEventListener("click", () => {
      if (submitting) return;
      clear();
      input.focus();
    });
    zone.addEventListener("dragover", (event) => {
      event.preventDefault();
      zone.dataset.dragging = "true";
    });
    zone.addEventListener("dragleave", (event) => {
      if (!zone.contains(event.relatedTarget)) delete zone.dataset.dragging;
    });
    zone.addEventListener("drop", (event) => {
      event.preventDefault();
      delete zone.dataset.dragging;
      choose(Array.from(event.dataTransfer?.files ?? []));
    });
    input.disabled = false;
    input.value = "";
  }

  // Dropping a file outside either card must not navigate away and lose the selection.
  for (const eventName of ["dragover", "drop"]) {
    root.addEventListener(eventName, (event) => {
      if (Array.from(event.dataTransfer?.types ?? []).includes("Files")) event.preventDefault();
    });
  }

  const connect = async () => {
    available = false;
    retry.hidden = true;
    updateCount();
    note.textContent = "Подключаемся к сервису обработки…";
    try {
      const session = await request("/api/session", { headers: { "X-WarpBuster-Request": "1" } });
      maxBytes = session.file_limit_bytes;
      available = true;
      note.textContent = `До ${formatFileSize(maxBytes)} на файл. Результат хранится ${session.retention_days} дней.`;
    } catch (error) {
      note.textContent = error.message;
      retry.hidden = false;
    }
    updateCount();
  };
  retry.addEventListener("click", connect);
  button.addEventListener("click", async () => {
    if (button.disabled) return;
    for (const extension of ["fit", "gpx"]) {
      if (extension === "gpx" && !selected.has("gpx")) continue;
      const message = validateSelection([selected.get(extension)], extension, maxBytes);
      if (message) { submitError.textContent = message; submitError.hidden = false; return; }
    }
    submissionKey ??= crypto.randomUUID();
    submitting = true;
    updateCount();
    button.textContent = "Загружаем файлы…";
    submitError.hidden = true;
    const inputs = root.querySelectorAll('input[type="file"], [data-remove]');
    inputs.forEach(input => { input.disabled = true; });
    try {
      const form = new FormData();
      form.append("activity", selected.get("fit"));
      if (selected.has("gpx")) form.append("course", selected.get("gpx"));
      const data = await request("/api/jobs", {
        method: "POST", body: form,
        headers: { "X-WarpBuster-Request": "1", "X-WarpBuster-Upload-ID": submissionKey },
      }, 75000);
      if (!/^[A-Za-z0-9_-]{43}$/.test(data.uid)) throw new Error("Сервер вернул некорректный результат.");
      openSubmittedResult(data.uid, browser);
    } catch (error) {
      submitError.textContent = error.message;
      submitError.hidden = false;
      if (error.status === 401) { available = false; retry.hidden = false; }
    } finally {
      submitting = false;
      button.textContent = "Проверить трек";
      inputs.forEach(input => { input.disabled = false; });
      updateCount();
    }
  });
  connect();
}

