  byId("new-upload").hidden = false;
}

function renderReport(data, status) {
  const [title, description] = resultMessage(data);
  byId("result-title").textContent = title;
  byId("result-description").textContent = description;
  byId("result-mode").textContent = data.mode === "fit_only" ? "Восстановление без GPX" : data.mode === "fit_with_course" ? "Восстановление с GPX" : "";
  byId("coverage-details").textContent = coverageDetails(data.observed_gps_coverage);
  byId("coverage-status").textContent = { passed: "GPS-данных достаточно для запуска восстановления", below_threshold: "Недостаточно GPS-данных", unavailable: "Покрытие GPS не определено", not_applicable: "" }[data.observed_gps_coverage?.status] || "";
  byId("coverage-message").textContent = coverageMessage(data.observed_gps_coverage);
  byId("coverage-message").hidden = !coverageRefused(data);
  byId("endpoint-note").textContent = endpointMessage(data);
  byId("endpoint-note").hidden = !byId("endpoint-note").textContent;
  byId("gap-details").hidden = !(data.gaps || []).length;
  byId("gap-rows").replaceChildren();
  for (const gap of data.gaps || []) {
    const row = document.createElement("tr");
    for (const value of gapCells(gap)) {
      const cell = document.createElement("td"); cell.textContent = value; row.append(cell);
    }
    byId("gap-rows").append(row);
  }
  byId("metric-changes").textContent = numeric.format(data.fit_diff?.changed_records || 0);
  byId("metric-before").textContent = distance(data.summary.original_distance_m);
  byId("metric-after").textContent = distance(data.summary.corrected_distance_m);
  byId("metric-gpx-gaps").textContent = numeric.format(data.summary.applied_gpx_gaps || 0);
  byId("metric-osm-gaps").textContent = numeric.format(data.summary.applied_osm_gaps || 0);
  byId("metric-unresolved-gaps").textContent = numeric.format(data.summary.unresolved_gaps || 0);
  const osmLabels = {
    not_needed: "OSM не потребовался",
    disabled: "OSM отключён оператором",
    complete: "OSM-проверка завершена",
    partial: "OSM-проверка завершена частично",
    unavailable: "Сбой при обработке OSM",
  };
  byId("osm-status").textContent = osmLabels[data.osm?.status] || "";
  byId("allocation-note").hidden = !(data.gaps || []).some(gap => gap.estimated);
  byId("osm-warning").textContent = osmFailureMessage(data);
  byId("osm-warning").hidden = !byId("osm-warning").textContent;
  const approximate = (data.approximate_osm?.decisions || []).filter(item => item.approximate && item.selected_route_id);
  byId("approximate-warning").hidden = approximate.length === 0;
  byId("approximate-warning").textContent = approximate.length
    ? "OSM-маршрут выбран приблизительно, фактический путь не подтверждён."
    : "";
  const dem = data.approximate_osm?.dem;
  byId("dem-status").hidden = !dem || dem.status === "disabled" || dem.status === "not_needed";
  byId("dem-status").textContent = dem?.status === "complete"
    ? "DEM-профиль проверен для выбора OSM-маршрута."
    : dem?.status === "unavailable" ? "DEM недоступен. Решение по маршруту принято по остальным доступным данным." : "";
  byId("altitude-status").textContent = altitudeMessage(data);
  byId("altitude-status").hidden = !byId("altitude-status").textContent;
  byId("owner-download").hidden = !status.can_download;
  byId("no-file-note").hidden = data.outcome === "repaired";
  byId("share-url").value = `${window.location.origin}/res/${uid}`;
  byId("expires-note").textContent = `Результат доступен до ${new Date(status.expires_at * 1000).toLocaleString("ru-RU")}.`;
  byId("diff-panel").hidden = !data.fit_diff;
  if (data.fit_diff) {
    const diff = data.fit_diff;
    byId("preservation-note").textContent = `Временные метки: ${diff.timestamps_unchanged ? "без изменений" : "изменены"}. Датчики, кроме явно дополненной высоты: ${(diff.non_altitude_sensors_unchanged ?? diff.sensors_unchanged) ? "без изменений" : "изменены"}. Поля разработчика и неизвестные поля: ${diff.developer_fields_unchanged && diff.unknown_fields_unchanged ? "сохранены" : "есть отличия"}.`;
    byId("diff-counts").textContent = `Изменено полей: ${diff.changed_fields}. Координаты: ${diff.coordinate_fields}, дистанция: ${diff.distance_fields}, агрегаты: ${diff.summary_fields}.` + (diff.truncated_changes ? ` Показана часть изменений; ещё ${diff.truncated_changes} не включены в таблицу.` : "");
    byId("diff-rows").replaceChildren();
    for (const change of diff.changes) {
      const row = document.createElement("tr");
      for (const value of [`${change.message}.${change.field}`, change.index, change.before ?? "—", change.after ?? "—"]) {
        const cell = document.createElement("td"); cell.textContent = String(value); row.append(cell);
      }
      byId("diff-rows").append(row);
    }
  }
  byId("waiting").hidden = true;
  byId("report").hidden = false;
  trackMap?.destroy();
  runSummary?.destroy();
  trackMap = createTrackMap(document, data.tracks, window.L, data.mode);
  runSummary = renderRunSummary(document, data.performance);
}

const poller = createResultPoller({
  getStatus: () => requestJson(`${endpoint}/status`),
  onReady: async status => {
    const report = await requestJson(endpoint);
    if (returnToUpload(report, uid)) return;
    finishResultNavigation(uid);
    renderReport(report, status);
  },
  onState: status => {
    if (status.status === "failed" || status.status === "expired") {
      finishResultNavigation(uid);
      showError(status.message || "Срок хранения результата истёк.", { title: "Обработка завершена без результата" });
      return;
    }
    byId("status-title").textContent = status.status === "processing" ? "Проверяем трек." : "Файлы приняты.";
    byId("status-message").textContent = status.status === "processing" ? "Ищем невозможные GPS-скачки и проверяем варианты восстановления." : "Трек в очереди. Обработка начнётся автоматически.";
  },
  onError: (error, terminal) => {
    if (terminal) showError(error.message, { retry: ![403, 404, 410].includes(error.status) });
    else byId("status-message").textContent = "Связь с сервером прервалась. Подключаемся снова…";
  },
});

byId("retry-status").addEventListener("click", () => {
  byId("spinner").hidden = false;
  byId("retry-status").hidden = true; byId("new-upload").hidden = true;
  byId("status-title").textContent = "Проверяем статус…"; poller.start();
});
byId("copy-link").addEventListener("click", async () => {
  try { await navigator.clipboard.writeText(byId("share-url").value); byId("copy-status").textContent = "Ссылка скопирована."; }
  catch { byId("share-url").focus(); byId("share-url").select(); byId("copy-status").textContent = "Скопируйте выделенную ссылку."; }
});
byId("download-fit").addEventListener("click", async () => {
  const button = byId("download-fit"); button.disabled = true;
  byId("download-error").hidden = true;
  try {
    const response = await fetch(`${endpoint}/download`, { credentials: "same-origin", cache: "no-store" });
    if (!response.ok) {
      const error = await response.json(); throw new ApiError(error.detail || "Скачивание недоступно.", response.status);
    }
    const url = URL.createObjectURL(await response.blob());
    const link = document.createElement("a"); link.href = url; link.download = "warpbuster-corrected.fit";
    document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 30000);
  } catch (error) {
    byId("download-error").textContent = error.message || "Не удалось скачать файл. Повторите попытку.";
    byId("download-error").hidden = false;
    if (error.status === 403) byId("owner-download").hidden = true;
  } finally { button.disabled = false; }
});
window.addEventListener("pagehide", () => poller.stop());
window.addEventListener("pageshow", event => { if (event.persisted) poller.start(); });
if (/^[A-Za-z0-9_-]{43}$/.test(uid)) poller.start();
else showError("Проверьте ссылку на результат.", { title: "Результат не найден" });

const number = new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 1 });
export const formatMetric = value => Number.isFinite(value) ? number.format(value) : "—";
export const formatWholeMetric = value => Number.isFinite(value) ? formatMetric(Math.round(value)) : "—";
export function formatDuration(seconds) {
  if (!Number.isFinite(seconds) || seconds < 0) return "—";
  const whole = Math.round(seconds), hours = Math.floor(whole / 3600);
  const minutes = Math.floor(whole / 60) % 60, rest = whole % 60;
  return hours ? `${hours}:${String(minutes).padStart(2, "0")}:${String(rest).padStart(2, "0")}`
    : `${minutes}:${String(rest).padStart(2, "0")}`;
}
export function formatPace(seconds) {
  if (!Number.isFinite(seconds) || seconds < 0) return "—";
  const whole = Math.round(seconds);
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}
export function splitLabel(split) {
  return split.complete_kilometre ? String(split.index)
    : `${number.format(split.start_distance_m / 1000)}–${number.format(split.end_distance_m / 1000)}`;
}

function svgElement(svg, name, attributes, text) {
  const element = svg.ownerDocument.createElementNS("http://www.w3.org/2000/svg", name);
  for (const [key, value] of Object.entries(attributes)) element.setAttribute(key, value);
  if (text !== undefined) element.textContent = text;
  return element;
}

export function drawSplitChart(svg, splits, elevation = false) {
  svg.replaceChildren();
  const width = Math.max(300, svg.clientWidth || 900), height = 240;
  svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
  const left = 55, right = width - 15, top = 20, bottom = height - 45;
  const fields = elevation ? ["ascent_m", "descent_m"] : ["pace_seconds_per_km"];
  const values = splits.flatMap(split => fields.map(field => split[field])).filter(Number.isFinite);
  const add = (name, attrs, text) => { const element = svgElement(svg, name, attrs, text); svg.append(element); return element; };
  if (!values.length) { add("text", { x: width / 2, y: 110, "text-anchor": "middle", class: "chart-label" }, "Нет данных"); return; }
  let max = 1;
  for (const value of values) max = Math.max(max, value);
  const y = value => bottom - value / max * (bottom - top);
  for (let i = 0; i <= 4; i++) {
    const value = max * i / 4;
    add("line", { x1: left, x2: right, y1: y(value), y2: y(value), class: "chart-grid" });
    add("text", { x: left - 8, y: y(value) + 4, "text-anchor": "end", class: "chart-label" }, elevation ? number.format(value) : formatPace(value));
  }
  const slot = (right - left) / splits.length, step = Math.max(1, Math.ceil(splits.length / Math.max(2, Math.floor(width / 70))));
  splits.forEach((split, index) => {
    const center = left + slot * (index + .5);
    fields.forEach((field, series) => {
      const value = split[field];
      if (!Number.isFinite(value)) return;
      const barWidth = Math.min(elevation ? 20 : 38, slot * (elevation ? .3 : .65));
      const x = elevation ? center + (series ? slot * .03 : -barWidth - slot * .03) : center - barWidth / 2;
      const rect = add("rect", { x, y: y(value), width: barWidth, height: Math.max(1, bottom - y(value)), rx: 2,
        fill: elevation && series ? "#b54b23" : "#203e31" });
      rect.append(svgElement(svg, "title", {}, `${splitLabel(split)} км: ${elevation ? `${series ? "сброс" : "набор"} ${formatMetric(value)} м` : `${formatPace(value)} мин/км`}`));
    });
    if (index % step === 0 || index === splits.length - 1) {
      add("text", { x: center, y: bottom + 22, "text-anchor": "middle", class: "chart-label" }, splitLabel(split));
    }
  });
  add("text", { x: (left + right) / 2, y: height - 3, "text-anchor": "middle", class: "chart-label" }, "Километр");
}

export function renderRunSummary(root, data) {
  const byId = id => root.getElementById(id);
  byId("run-empty").hidden = Boolean(data);
  byId("run-content").hidden = !data;
  byId("run-source").textContent = data ? (data.source === "corrected" ? "По исправленному FIT" : "По исходному FIT") : "";
  if (!data) return { destroy() {} };
  byId("distance-warning").hidden = !["uncertain", "unknown"].includes(data.distance_quality);
  byId("distance-warning").textContent = data.distance_quality === "unknown"
    ? "Для этого ранее созданного результата качество дистанции и темпа не определено."
    : "Дистанция и темп могут быть неточными: часть данных осталась неопределённой.";
  byId("run-pace").textContent = Number.isFinite(data.average_pace_seconds_per_km) ? `${formatPace(data.average_pace_seconds_per_km)} /км` : "—";
  byId("run-time").textContent = formatDuration(data.timer_duration_seconds);
  byId("run-ascent").textContent = Number.isFinite(data.total_ascent_m) ? `↑ ${formatMetric(data.total_ascent_m)} м` : "—";
  byId("run-descent").textContent = Number.isFinite(data.total_descent_m) ? `↓ ${formatMetric(data.total_descent_m)} м` : "—";
  byId("cadence-heading").textContent = data.cadence_unit === "steps_per_minute" ? "Каденс, шаг/мин" : "Каденс, /мин";
  const splits = data.splits || [];
  byId("splits-empty").hidden = splits.length > 0;
  byId("splits-content").hidden = !splits.length;
  byId("split-rows").replaceChildren();
  const fragment = root.createDocumentFragment();
  for (const split of splits) {
    const row = root.createElement("tr");
    const values = [splitLabel(split), `${formatMetric(split.distance_m)} м`, formatDuration(split.elapsed_seconds),
      formatPace(split.pace_seconds_per_km), `${formatWholeMetric(split.ascent_m)} / ${formatWholeMetric(split.descent_m)} м`,
      formatWholeMetric(split.average_heart_rate_bpm), formatWholeMetric(split.average_cadence),
      Number.isFinite(split.coordinate_coverage_ratio) ? `${Math.round(split.coordinate_coverage_ratio * 100)}%` : "—"];
    for (const value of values) { const cell = root.createElement("td"); cell.textContent = value; row.append(cell); }
    fragment.append(row);
  }
  byId("split-rows").append(fragment);
  const render = () => {
    drawSplitChart(byId("pace-chart"), splits);
    drawSplitChart(byId("elevation-chart"), splits, true);
  };
  render();
  const observer = new ResizeObserver(render);
  observer.observe(byId("run-summary"));
  return { destroy() { observer.disconnect(); } };
}
